CREATE VIEW market_registry_rows AS SELECT coalesce(m.id::text,'') as id, coalesce(m.slug::text,'') as slug, coalesce(m.question::text,'') as question, coalesce(m.category_id::text,'') as category_id, coalesce(m.season_id::text,'') as season_id, coalesce(m.resolution_source_id::text,'') as resolution_source_id, coalesce(m.rules->>'yes_if','') as yes_if, coalesce(m.rules->>'no_if','') as no_if, coalesce(m.rules->>'edge_cases','') as edge_cases, coalesce((extract(epoch from m.open_at)*1000)::bigint,0) as open_at, coalesce((extract(epoch from m.close_at)*1000)::bigint,0) as close_at, coalesce((extract(epoch from m.resolve_by)*1000)::bigint,0) as resolve_by, coalesce(m.redemption_units,0) as redemption_units, coalesce(m.min_price,0) as min_price, coalesce(m.max_price,0) as max_price, coalesce(m.tick,0) as tick, coalesce(m.max_order_qty,0) as max_order_qty, coalesce(m.fee_units,0) as fee_units, coalesce(m.min_order_notional,0) as min_order_notional, coalesce(m.liquidity_request,0) as liquidity_request, coalesce(m.featured_rank,0) as featured_rank, coalesce(m.opening_price,0) as opening_price, coalesce(m.status::text,'') as status, coalesce(m.version,0) as version, coalesce(m.terms_version,0) as terms_version, coalesce(m.terms_hash::text,'') as terms_hash, coalesce(m.created_by::text,'') as created_by, coalesce(m.submitted_by::text,'') as submitted_by, coalesce(m.approved_by::text,'') as approved_by, coalesce((extract(epoch from m.created_at)*1000)::bigint,0) as created_at, coalesce((extract(epoch from m.updated_at)*1000)::bigint,0) as updated_at, coalesce((extract(epoch from m.opened_at)*1000)::bigint,0) as opened_at, coalesce((extract(epoch from m.closed_at)*1000)::bigint,0) as closed_at, coalesce((extract(epoch from m.suspended_at)*1000)::bigint,0) as suspended_at, coalesce(m.suspend_reason::text,'') as suspend_reason, coalesce(m.status_note::text,'') as status_note FROM markets m;
GRANT SELECT ON market_registry_rows TO say_app;
